package com.airesumebuilder.feature.audit.listener;
import static org.mockito.Mockito.*;import com.airesumebuilder.events.*;import com.airesumebuilder.feature.audit.service.AuditService;import java.util.Map;import org.junit.jupiter.api.Test;
class ResumeAuditListenerTest{@Test void persistsCreateUpdateAndDeleteEvents(){AuditService audit=mock(AuditService.class);ResumeAuditListener listener=new ResumeAuditListener(audit);listener.created(new ResumeCreatedEvent(3L,2L));listener.updated(new ResumeUpdatedEvent(3L,2L,Map.of("title","old"),Map.of("title","new")));listener.deleted(new ResumeDeletedEvent(3L,2L,Map.of("title","new")));verify(audit).record(2L,"Resume",3L,"CREATED",Map.of("resumeId",3L));verify(audit).recordChange(2L,"Resume",3L,"UPDATED",Map.of("title","old"),Map.of("title","new"));verify(audit).recordChange(2L,"Resume",3L,"DELETED",Map.of("title","new"),Map.of("deleted",true));}}
